content.content:
    end = as_utc(run.finished_at) if run.finished_at is not None else _now()
    return max(int((end - started).total_seconds() * 1000), 0)


# ── sample-failures redaction (PII-safe surfacing on the read API) ────────────

# Safe aggregate keys only; everything else is potential PII and masked. Mirrors
# the producer's `gx_runner._SAMPLE_KEYS` — keep in sync or new keys get masked.
_SAMPLE_SAFE_KEYS = frozenset({"unexpected_count", "unexpected_percent"})
# Same sentinel as core.logging._REDACTED; the two redactors stay separate.
_REDACTED_VALUE = "<redacted>"

# `VALUE_SIGNAL_SUMMARY_KEY` (#1230) is shared with the writer via `datasources.base`;
# consumed for classification, then dropped from the redacted output.


def _redact_sample_value(value: Any) -> Any:
    """Mask data values while preserving container shape and dict keys."""
    if isinstance(value, dict):
        return {key: _redact_sample_value(val) for key, val in value.items()}
    if isinstance(value, list):
        return [_redact_sample_value(item) for item in value]
    return _REDACTED_VALUE


# Tag values that HARD-mask a column (#415 level 1 — a floor no override lifts).
_SENSITIVE_TAG_VALUES = frozenset({"sensitive", "pii", "confidential", "restricted", "secret"})


def _tag_value(column: str, tags: Mapping[str, str] | None) -> str:
    """The governance map's verdict for a column, lower-cased, or `""` — the ONE lookup the
    three tag rungs below share, so how a column name is matched can never diverge between them.
    """
    if not tags:
        return ""
    tag = tags.get(column) or tags.get(fold_key(column)) or ""
    return str(tag).strip().lower()


def _tag_sensitive(column: str, tags: Mapping[str, str] | None) -> bool:
    """Level 1 — a datasource governance tag marks the column sensitive (hard floor)."""
    return _tag_value(column, tags) in _SENSITIVE_TAG_VALUES


def _policy_requires_classification(policy: Mapping[str, Any] | None) -> bool:
    """Whether this suite is in **fail-closed** mode (G3 / #433)."""
    return bool(policy and policy.get("require_classification"))


#: Tag values that explicitly clear a column; consulted only in fail-closed mode.
#: `internal` is deliberately absent — a confidentiality level, not a no-PII assertion.
_NON_SENSITIVE_TAG_VALUES = frozenset({"public", "non_sensitive", "nonsensitive"})


def _tag_non_sensitive(column: str, tags: Mapping[str, str] | None) -> bool:
    """Level 1, the allow side — a governance tag explicitly clears the column."""
    return _tag_value(column, tags) in _NON_SENSITIVE_TAG_VALUES


def _detected_sensitive(column: str, tags: Mapping[str, str] | None) -> bool:
    """Level 2 (ADR 0049) — the profiler has detected PII-shaped VALUES in this column and the
    verdict is persisted. Below the warehouse floor and the suite override: `pii_columns`
    masks it regardless, `identifier_column` clears it, and it never satisfies fail-closed
    clearance — the value is deliberately in neither tag set above.
    """
    return _tag_value(column, tags) == DETECTED


def _policy_pii(column: str, policy: Mapping[str, Any] | None) -> bool:
    """Level 3 — the suite override explicitly lists the column as PII."""
    if not policy:
        return False
    listed = {str(c).strip().lower() for c in (policy.get("pii_columns") or [])}
    return column.strip().lower() in listed


def _policy_identifier(column: str, policy: Mapping[str, Any] | None) -> bool:
    """Level 3 — the suite override names the column as the shown identifier."""
    if not policy:
        return False
    ident = policy.get("identifier_column")
    return bool(ident) and str(ident).strip().lower() == column.strip().lower()


# Which rung of the ladder masked a column (#2255) — a closed vocabulary, reported beside
# `redacted_columns` on every surface that shows the list. Ordered as the ladder consults them.
RedactionReason = Literal[
    "own_tag",  # the column's own warehouse classification (G3 floor)
    "inherited_tag",  # `sensitive` inherited through recorded column lineage (#1710)
    "policy",  # the suite's `pii_columns`
    "unclassified",  # fail-closed mode (`require_classification`) and nothing cleared it
    "detected",  # the profiler found PII-shaped values at profile time (ADR 0049)
    "classifier",  # the read-time name / value heuristic affirmatively says PII
    "default_mask",  # an incidental column nobody classified — precautionary (#415)
]
REDACTION_REASONS: tuple[RedactionReason, ...] = get_args(RedactionReason)


def _tag_mask_reason(column: str, tags: Mapping[str, str] | None) -> RedactionReason | None:
    """Level 1 as a reason: `own_tag` / `inherited_tag` when the tag masks, else `None`."""
    if not _tag_sensitive(column, tags):
        return None
    return "inherited_tag" if fold_key(column) in inherited_tag_columns(tags) else "own_tag"


def _floor_mask_reason(
    column: str, policy: Mapping[str, Any] | None, tags: Mapping[str, str] | None
) -> RedactionReason | None:
    """The two rungs no override lifts, in order: the governance tag, then `pii_columns`."""
    return _tag_mask_reason(column, tags) or ("policy" if _policy_pii(column, policy) else None)


def _known_sensitive_reason(
    column: str,
    values: Sequence[Any],
    policy: Mapping[str, Any] | None,
    tags: Mapping[str, str] | None,
    *,
    value_signal_summary: Mapping[str, Any] | None = None,
) -> RedactionReason | None:
    """`_known_sensitive`, answering WHICH rung decided; `None` means not known sensitive."""
    floor = _floor_mask_reason(column, policy, tags)
    if floor is not None:
        return floor
    if _policy_requires_classification(policy):
        # Fail-closed (G3): "known sensitive" becomes "not known SAFE".
        cleared = _tag_non_sensitive(column, tags) or _policy_identifier(column, policy)
        if not cleared:
            return "unclassified"
        if is_sensitive(column, values, value_signal_summary=value_signal_summary):
            return "classifier"
        return None
    # A persisted profiler detection masks unless the operator named THIS column as the shown
    # identifier — on a datasource with no warehouse tag that is a false positive's only exit.
    if _detected_sensitive(column, tags) and not _policy_identifier(column, policy):
        return "detected"
    if is_sensitive(column, values, value_signal_summary=value_signal_summary):
        return "classifier"
    return None


def _known_sensitive(
    column: str,
    values: Sequence[Any],
    policy: Mapping[str, Any] | None,
    tags: Mapping[str, str] | None,
    *,
    value_signal_summary: Mapping[str, Any] | None = None,
) -> bool:
    """Whether a column is **known** sensitive — a governance tag (floor), an explicit
    override, or an *affirmative* name/value PII signal (not the conservative default).
    Gates the **tested** and **identifier** columns: those are shown *unless* known
    sensitive (seeing the failing value / locating the row is the point).
    """
    return (
        _known_sensitive_reason(
            column, values, policy, tags, value_signal_summary=value_signal_summary
        )
        is not None
    )


def _incidental_mask_reason(
    column: str,
    values: Sequence[Any],
    policy: Mapping[str, Any] | None,
    tags: Mapping[str, str] | None,
    *,
    value_signal_summary: Mapping[str, Any] | None = None,
) -> RedactionReason | None:
    """`_may_show_incidental`, answering WHICH rung masked; `None` means the column may show."""
    floor = _floor_mask_reason(column, policy, tags)
    if floor is not None:
        return floor
    if _policy_requires_classification(policy):
        # Fail-closed (G3): shown only on explicit clearance AND nothing affirmatively
        # sensitive — dropping either half breaks or LOOSENS the mode.
        if not (_tag_non_sensitive(column, tags) or _policy_identifier(column, policy)):
            return "unclassified"
        if is_sensitive(column, values, value_signal_summary=value_signal_summary):
            return "classifier"
        return None
    if _policy_identifier(column, policy):
        if is_sensitive(column, values, value_signal_summary=value_signal_summary):
            return "classifier"
        return None
    if _detected_sensitive(column, tags):
        return "detected"
    # One classifier pass: PII either from an affirmative signal (`classifier`) or because the
    # column could not be placed at all — the precautionary default mask (#415).
    verdict, affirmative = classify_column_with_basis(
        column, list(values), value_signal_summary=value_signal_summary
    )
    if verdict is not ColumnClass.PII:
        return None
    return "classifier" if affirmative else "default_mask"


def _may_show_incidental(
    column: str,
    values: Sequence[Any],
    policy: Mapping[str, Any] | None,
    tags: Mapping[str, str] | None,
    *,
    value_signal_summary: Mapping[str, Any] | None = None,
) -> bool:
    """Whether an *incidental* column (not the tested / identifier one) may be shown: only when
    it's affirmatively an IDENTIFIER or SAFE value — everything else default-masks (#415), so
    security can't regress.
    """
    return (
        _incidental_mask_reason(
            column, values, policy, tags, value_signal_summary=value_signal_summary
        )
        is None
    )


def value_signal_decides(
    column: str, policy: Mapping[str, Any] | None, tags: Mapping[str, str] | None
) -> bool:
    """Whether a column's failing-row VALUES can change its masking — the negation of every
    rung that decides without them: a sensitive tag or `pii_columns` (masked), a PII-shaped
    name (masked by `is_sensitive` either way), a persisted profiler detection the operator has
    not overridden with `identifier_column` (masked, ADR 0049), or fail-closed mode without
    clearance (masked).
    Mirrors `_known_sensitive` / `_may_show_incidental`, which share those rungs; the SQL lanes
    pay for a population sample only when this is True (#2014).
    """
    if _tag_sensitive(column, tags) or _policy_pii(column, policy):
        return False
    if is_sensitive(column, ()):
        return False
    if _detected_sensitive(column, tags) and not _policy_identifier(column, policy):
        return False
    if _policy_requires_classification(policy):
        return _tag_non_sensitive(column, tags) or _policy_identifier(column, policy)
    return True


def build_value_signal_gate(
    policy: Mapping[str, Any] | None, tags: Mapping[str, str] | None
) -> ValueSignalGate:
    """`value_signal_decides` bound to a run's capture-time policy and warehouse tags."""
    policy_snapshot = copy.deepcopy(dict(policy or {}))
    tags_snapshot = copy_tags(tags)

    def gate(column: str) -> bool:
        return value_signal_decides(column, policy_snapshot, tags_snapshot)

    return gate


def _values_by_column(rows: Sequence[Any]) -> dict[str, list[Any]]:
    """Gather each column's values across the sampled failing rows, so the classifier's
    value signal (emails, id-shape) sees the whole column, not one cell.
    """
    out: dict[str, list[Any]] = defaultdict(list)
    for row in rows:
        if isinstance(row, dict):
            for col, val in row.items():
                out[str(col)].append(val)
    return dict(out)


# Redaction summary surfaced beside `sample_failures` (#424/#415); `zero_sample` (#1873)
# distinguishes a null sample SUPPRESSED by zero-sample mode (#1676) from one that was
# genuinely empty — both read `null` on the wire otherwise.
RedactionState = Literal["full", "partial", "none", "zero_sample"]


@dataclass
class _RedactionTracker:
    """Accumulates per-column show/mask decisions across one `redact_sample_failures`
    call, so the caller can report an honest summary instead of re-sniffing the
    redacted output for the `"<redacted>"` sentinel (fragile — a genuine cell value
    equal to the sentinel would misreport, and it can't see counts).
    """

    column_state: dict[str, bool] = field(default_factory=dict)
    column_reason: dict[str, RedactionReason] = field(default_factory=dict)
    anonymous_masked: bool = False

    def record(
        self, column: str | None, shown: bool, reason: RedactionReason | None = None
    ) -> None:
        if column:
            self.column_state[column] = self.column_state.get(column, False) or shown
            if not shown and reason is not None:
                # A comparison sample runs the ladder per bucket, so one column can get two
                # reasons (opaque values in one bucket, emails in another). Keep the strongest —
                # earliest on the ladder — so an affirmative verdict is never reported as the
                # precautionary `default_mask`.
                held = self.column_reason.get(column)
                if held is None or REDACTION_REASONS.index(reason) < REDACTION_REASONS.index(held):
                    self.column_reason[column] = reason
        elif not shown:
            self.anonymous_masked = True

    def summary(self) -> tuple[RedactionState | None, list[str]]:
        """`(state, redacted_columns)`. ``state`` is ``None`` when nothing data-bearing was seen
        (e.g. only aggregate counts, or an empty sample) — there is nothing true to claim either
        way, so the caller should omit any redaction label rather than guess.
        ``redacted_columns`` lists columns that were masked everywhere they appeared (never
        shown).
        """
        shown_any = any(self.column_state.values())
        masked_any = any(not shown for shown in self.column_state.values()) or self.anonymous_masked
        redacted_columns = sorted(name for name, shown in self.column_state.items() if not shown)
        if not shown_any and not masked_any:
            return None, []
        if masked_any and not shown_any:
            return "full", redacted_columns
        if shown_any and not masked_any:
            return "none", redacted_columns
        return "partial", redacted_columns

    def reasons(self) -> dict[str, RedactionReason]:
        """Why each entry of ``redacted_columns`` was masked (#2255) — the same key set, every
        time. A masked column with no recorded rung is a bug: it is logged and left OUT of the
        map rather than labelled ``default_mask``, which would assert "never classified" about a
        column that may well have been (a confident wrong answer)."""
        out: dict[str, RedactionReason] = {}
        for name, shown in sorted(self.column_state.items()):
            if shown:
                continue
            reason = self.column_reason.get(name)
            if reason is None:
                log.error("redaction_reason_missing", column_count=1)
                continue
            out[name] = reason
        return out


